-- Read-only lane performance derived from verified completed loads. No market pricing is inferred.
begin;
create or replace function public.list_verified_lane_performance(p_start date,p_end date)returns table(origin_city text,origin_state text,destination_city text,destination_state text,load_count bigint,rated_load_count bigint,mileage_load_count bigint,revenue_cents bigint,total_miles bigint,average_rate_cents bigint,average_rpm_cents bigint,last_completed_at timestamptz,excluded_missing_lane_count bigint)
language plpgsql stable security definer set search_path=public as $$declare c uuid:=public.document_intake_company_id();r text:=public.current_business_role();begin if c is null or auth.uid()is null or r not in('super_admin','owner','dispatcher','accounting')then raise exception'Not authorized';end if;if p_start is null or p_end is null or p_end<p_start or p_end>current_date+1 or p_end-p_start>366 then raise exception'Invalid lane period';end if;return query with completed as(select l.id,l.miles,f.rate_cents,e.event_at,p.city origin_city,p.state origin_state,d.city destination_city,d.state destination_state from public.loads l join lateral(select x.event_at from public.load_events x where x.company_id=l.company_id and x.load_id=l.id and x.event_type='status_changed'and x.status in('delivered','closed')order by x.event_at desc limit 1)e on e.event_at::date between p_start and p_end left join lateral(select s.city,s.state from public.load_stops s where s.company_id=l.company_id and s.load_id=l.id and s.stop_type='pickup'order by s.stop_sequence limit 1)p on true left join lateral(select s.city,s.state from public.load_stops s where s.company_id=l.company_id and s.load_id=l.id and s.stop_type='delivery'order by s.stop_sequence desc limit 1)d on true left join public.load_financials f on f.company_id=l.company_id and f.load_id=l.id where l.company_id=c and l.status in('delivered','closed')),missing as(select count(*)::bigint total from completed where nullif(trim(origin_city),'')is null or nullif(trim(origin_state),'')is null or nullif(trim(destination_city),'')is null or nullif(trim(destination_state),'')is null),lanes as(select trim(origin_city)o_city,upper(trim(origin_state))o_state,trim(destination_city)d_city,upper(trim(destination_state))d_state,count(*)::bigint loads,count(*)filter(where rate_cents is not null)::bigint rated,count(*)filter(where miles is not null and miles>0)::bigint mileage,coalesce(sum(rate_cents)filter(where rate_cents is not null),0)::bigint revenue,coalesce(sum(miles)filter(where miles is not null and miles>0),0)::bigint miles,round(avg(rate_cents)filter(where rate_cents is not null))::bigint avg_rate,round(avg(rate_cents::numeric/miles)filter(where rate_cents is not null and miles is not null and miles>0))::bigint avg_rpm,max(event_at)last_at from completed where nullif(trim(origin_city),'')is not null and nullif(trim(origin_state),'')is not null and nullif(trim(destination_city),'')is not null and nullif(trim(destination_state),'')is not null group by trim(origin_city),upper(trim(origin_state)),trim(destination_city),upper(trim(destination_state)))select l.o_city,l.o_state,l.d_city,l.d_state,l.loads,l.rated,l.mileage,l.revenue,l.miles,l.avg_rate,l.avg_rpm,l.last_at,m.total from lanes l cross join missing m order by l.loads desc,l.last_at desc;end$$;
revoke all on function public.list_verified_lane_performance(date,date)from public,anon;grant execute on function public.list_verified_lane_performance(date,date)to authenticated;commit;
